modes.detail:
// ============ 和 03-04 的差别只有下标公式 ============
//
// 回顾一下下沉在做什么：
//
//   ① 看两个**孩子**里谁更大
//   ② 如果自己 >= 那个更大的孩子，位置对了，停
//   ③ 否则把孩子搬上来、自己继续往下
//
// 这里是**最大堆**（父 >= 子），所以找的是"更大的孩子" ——
// 03-04 讲最小堆时找的是"更小的孩子"，方向正好相反。
//
// ============ 为什么要带 N 这个参数 ============
//
// 因为堆排序的过程中，堆会**越来越小**：
//
//   每轮把堆顶换到数组末尾，末尾那个位置就"退出堆"了
//   下一轮下沉时就不能越过它
//
// 所以 N 是"当前堆的大小"，不是整个数组的长度。
// 这是堆排序里最容易被忽略的地方 —— 忘了改 N，排序结果就全乱了。

// 在下标 [0, N) 这个范围内，把 A[p] 往下沉到合适的位置
void PercDown(ElementType A[], int p, int N)
{
// 父结点下标（一路往下走）
    int parent;
// 较大的孩子下标
    int child;
// 暂存要下沉的元素
    ElementType x;

// 取出要下沉的元素
    x = A[p];

// 沿着"较大的孩子"一路往下
// 0 起始下标的左孩子是 2*parent + 1。
    for (parent = p; parent * 2 + 1 < N; parent = child)
    {
// 先假设较大的孩子是左孩子
        child = parent * 2 + 1;

// 如果有右孩子、且右孩子更大，就换成右孩子
// `child != N - 1` 判断有没有右孩子：N-1 是堆里最后一个下标，
// 如果左孩子正好是最后一个，那就没有右孩子。
        if (child != N - 1 && A[child] < A[child + 1])
        {
            child++;
        }

// 自己已经不小于那个较大的孩子 → 位置对了
        if (x >= A[child])
        {
            break;
        }

// 否则把孩子搬上来，自己继续往下比
        A[parent] = A[child];
    }

// 落位
    A[parent] = x;
}

