modes.detail:
// ============ 合并做的事 ============
//
// 假设数组里有两段**各自已经有序**：
//
//   下标  0  1  2  |  3  4  5
//   值    1  5  8     2  4  9
//         ← 左段 →     ← 右段 →
//
// 要把它们合并成一个有序的 { 1, 2, 4, 5, 8, 9 }。
//
// 做法就是**两个人比大小**：
//
//   左段指针在 1，右段指针在 2 → 1 小，取 1
//   左段指针在 5，右段指针在 2 → 2 小，取 2
//   左段指针在 5，右段指针在 4 → 4 小，取 4
//   左段指针在 5，右段指针在 9 → 5 小，取 5
//   左段指针在 8，右段指针在 9 → 8 小，取 8
//   左段空了，右段剩下的直接搬过来 → 9
//
// ============ 为什么要用额外数组 ============
//
// 因为**不能就地合并**：
//
// 如果直接在原数组里写，A[0] 被新值覆盖之后，原来那个 1 就没了。
// 所以必须先把结果放到一个临时数组里，最后再整段拷回去。
//
// 这就是归并排序"需要 O(n) 额外空间"的来源 —— 也是它最大的缺点。
//
// ============ 稳定性就藏在一个符号里 ============
//
// 比较时写的是 `A[L] <= A[R]`，**带了等号**。
//
// 意思是"两边相等时优先取左边的"。因为左边的元素在原数组里本来就更靠前，
// 优先取它能保持相对顺序 —— **这就保证了归并排序是稳定的**。
//
// 如果写成 `<`，相等时就会取右边的，稳定性就没了。
//
// ============ 参数为什么这么别扭 ============
//
// 这里用的是教材里的经典写法，参数是 (L, R, RightEnd)：
//
//     L        左段的起点
//     R        右段的起点（同时也是左段的终点 + 1）
//     RightEnd 右段的终点
//
// 于是左段是 [L, R-1]、右段是 [R, RightEnd]。
// 这样传参的好处是**不用再单独传"左段终点"** —— 它等于 R-1。

// 把 A[L..R-1] 和 A[R..RightEnd] 两段合并
// 结果先放 TmpA，最后拷回 A
void Merge(ElementType A[], ElementType TmpA[], int L, int R, int RightEnd)
{
// 左段的终点（右段起点左边那个）
    int LeftEnd = R - 1;
// 往 TmpA 里填的位置
    int Tmp = L;
// 本段一共多少个元素（拷回时要用）
    int NumElements = RightEnd - L + 1;
// 循环用
    int i;

// 两边都还有元素时，比较着取
    while (L <= LeftEnd && R <= RightEnd)
    {
// 左边不大于右边 → 取左边
// 这里的 `<=` 就是稳定性的保证：相等时优先取左边（原数组里更靠前的）。
        if (A[L] <= A[R])
        {
            TmpA[Tmp++] = A[L++];
        }
// 否则取右边
        else
        {
            TmpA[Tmp++] = A[R++];
        }
    }

// 左边还有剩的，直接搬
    while (L <= LeftEnd)
    {
        TmpA[Tmp++] = A[L++];
    }

// 右边还有剩的，直接搬
    while (R <= RightEnd)
    {
        TmpA[Tmp++] = A[R++];
    }

// 把合并结果拷回原数组
// 从后往前拷，正好和 RightEnd 递减对上。
    for (i = 0; i < NumElements; i++, RightEnd--)
    {
        A[RightEnd] = TmpA[RightEnd];
    }
}

