// 把 A[L..R-1] 和 A[R..RightEnd] 两段合并
void Merge(ElementType A[], ElementType TmpA[], int L, int R, int RightEnd)
{
// 左段的终点（右段起点左边那个）
    int LeftEnd = R - 1;
// 往 TmpA 里填的位置
    int Tmp = L;
// 本段一共多少个元素（拷回时要用）
    int NumElements = RightEnd - L + 1;
// 循环用
    int i;

// 两边都还有元素时，比较着取
    while (L <= LeftEnd && R <= RightEnd)
    {
// 左边不大于右边 → 取左边
        if (A[L] <= A[R])
        {
            TmpA[Tmp++] = A[L++];
        }
// 否则取右边
        else
        {
            TmpA[Tmp++] = A[R++];
        }
    }

// 左边还有剩的，直接搬
    while (L <= LeftEnd)
    {
        TmpA[Tmp++] = A[L++];
    }

// 右边还有剩的，直接搬
    while (R <= RightEnd)
    {
        TmpA[Tmp++] = A[R++];
    }

// 把合并结果拷回原数组
    for (i = 0; i < NumElements; i++, RightEnd--)
    {
        A[RightEnd] = TmpA[RightEnd];
    }
}

