modes.detail:
// ============ 为什么要单独包一层 ============
//
// 临时数组 TmpA **只需要分配一次**，而不是每次 Merge 都分配。
//
// 如果在 Merge 里面 malloc，那要 malloc n 次，开销巨大 ——
// 这是初学者很容易犯的错。
//
// 所以 MSort 把 TmpA 当作参数一路传下去，只在最外层分配一次。
// 用户调用时只需要传数组和长度。
//
// ============ 分配失败怎么办 ============
//
// 归一化处理：打印一行提示就返回，不至于让程序崩掉。
// 实际工程里可能会退化到别的排序（比如堆排序，它不需要额外空间）。

// 归并排序（对外的接口）
void MergeSort(ElementType A[], int N)
{
// 临时数组
    ElementType *TmpA = (ElementType *)malloc(N * sizeof(ElementType));

// 分配失败就不用归并了（原地算法没有这个风险）
    if (TmpA == NULL)
    {
        printf("临时空间分配失败，无法归并排序\n");
        return;
    }

// 调用分治
    MSort(A, TmpA, 0, N - 1);

// 释放临时空间
    free(TmpA);
}

