#include <stdio.h>
#include <stdlib.h>


// 元素类型
typedef int ElementType;

// 状态码
#define OK 1
#define ERROR 0
typedef int Status;

// 交换两个元素
void Swap(ElementType *a, ElementType *b)
{
// 临时变量倒手
    ElementType t = *a;
    *a = *b;
    *b = t;
}


// 在下标 [0, N) 这个范围内，把 A[p] 往下沉到合适的位置
void PercDown(ElementType A[], int p, int N)
{
// 父结点下标（一路往下走）
    int parent;
// 较大的孩子下标
    int child;
// 暂存要下沉的元素
    ElementType x;

// 取出要下沉的元素
    x = A[p];

// 沿着"较大的孩子"一路往下
    for (parent = p; parent * 2 + 1 < N; parent = child)
    {
// 先假设较大的孩子是左孩子
        child = parent * 2 + 1;

// 如果有右孩子、且右孩子更大，就换成右孩子
        if (child != N - 1 && A[child] < A[child + 1])
        {
            child++;
        }

// 自己已经不小于那个较大的孩子 → 位置对了
        if (x >= A[child])
        {
            break;
        }

// 否则把孩子搬上来，自己继续往下比
        A[parent] = A[child];
    }

// 落位
    A[parent] = x;
}


// 堆排序（升序）
void HeapSort(ElementType A[], int N)
{
// 循环用
    int i;

// 阶段一：从最后一个非叶结点开始，逐个下沉，建成最大堆
    for (i = N / 2 - 1; i >= 0; i--)
    {
        PercDown(A, i, N);
    }

// 阶段二：反复把堆顶换到末尾
    for (i = N - 1; i > 0; i--)
    {
// 堆顶（当前最大值）换到末尾
        Swap(&A[0], &A[i]);

// 堆缩小一格，然后恢复堆序
        PercDown(A, 0, i);
    }
}


// 把 A[L..R-1] 和 A[R..RightEnd] 两段合并
void Merge(ElementType A[], ElementType TmpA[], int L, int R, int RightEnd)
{
// 左段的终点（右段起点左边那个）
    int LeftEnd = R - 1;
// 往 TmpA 里填的位置
    int Tmp = L;
// 本段一共多少个元素（拷回时要用）
    int NumElements = RightEnd - L + 1;
// 循环用
    int i;

// 两边都还有元素时，比较着取
    while (L <= LeftEnd && R <= RightEnd)
    {
// 左边不大于右边 → 取左边
        if (A[L] <= A[R])
        {
            TmpA[Tmp++] = A[L++];
        }
// 否则取右边
        else
        {
            TmpA[Tmp++] = A[R++];
        }
    }

// 左边还有剩的，直接搬
    while (L <= LeftEnd)
    {
        TmpA[Tmp++] = A[L++];
    }

// 右边还有剩的，直接搬
    while (R <= RightEnd)
    {
        TmpA[Tmp++] = A[R++];
    }

// 把合并结果拷回原数组
    for (i = 0; i < NumElements; i++, RightEnd--)
    {
        A[RightEnd] = TmpA[RightEnd];
    }
}


// 把 A[L..RightEnd] 归并排序，TmpA 是临时空间
void MSort(ElementType A[], ElementType TmpA[], int L, int RightEnd)
{
// 中间位置
    int Center;

// 至少两个元素才需要处理（一个元素本身有序）
    if (L < RightEnd)
    {
// ① 分：从中间劈开
        Center = (L + RightEnd) / 2;

// ② 治：左半边排好
        MSort(A, TmpA, L, Center);

// 治：右半边排好
        MSort(A, TmpA, Center + 1, RightEnd);

// ③ 合：两段都已经有序，合并它们
        Merge(A, TmpA, L, Center + 1, RightEnd);
    }
}


// 归并排序（对外的接口）
void MergeSort(ElementType A[], int N)
{
// 临时数组
    ElementType *TmpA = (ElementType *)malloc(N * sizeof(ElementType));

// 分配失败就不用归并了（原地算法没有这个风险）
    if (TmpA == NULL)
    {
        printf("临时空间分配失败，无法归并排序\n");
        return;
    }

// 调用分治
    MSort(A, TmpA, 0, N - 1);

// 释放临时空间
    free(TmpA);
}


void PrintArray(const ElementType A[], int N)
{
// 循环用
    int i;

    printf("[");
    for (i = 0; i < N; i++)
    {
        printf("%d", A[i]);
        if (i < N - 1)
